                <?php $__fi = $post['featured_image'] ?? ''; ?>
                <img id="featuredImagePreview" src="<?= htmlspecialchars($__fi, ENT_QUOTES, 'UTF-8') ?>"
                     alt="" class="w-full rounded-xl border border-slate-100 dark:border-slate-800 <?= $__fi === '' ? 'hidden' : '' ?>">
                <!-- the featured image is uploaded via the same /upload API as body images (sharing EXIF removal, attachments recording, physical isolation).
                     The value (a path pointing to an attachments file) is kept in a hidden field. The fallback is resolved at save time. -->
                <input type="hidden" name="featured_image" id="featuredImageInput" value="{{ $post['featured_image'] }}">
                <!-- uploadable even during new creation (the first upload auto-generates a draft; same /upload as body images) -->
