                <div class="flex items-center gap-2">
                    <button type="button" onclick="uploadFeatured()" class="flex-1 text-xs bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 py-2 rounded-xl transition-colors">{@ featured_upload @}</button>
