                <p class="text-[11px] text-slate-400">{@ featured_image_hint @}</p>
                <div>
                    <label class="block text-xs text-slate-400 mb-1">{@ featured_image_alt @}</label>
                    <input type="text" name="featured_image_alt" value="{{ $post['featured_image_alt'] }}"
                           class="w-full text-xs px-3 py-2 border border-slate-200 dark:border-slate-700 rounded-xl dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:border-emerald-500">
                </div>
            </div>

            <!-- SEO settings -->
            <div class="bg-white dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl p-4 space-y-3">
                <p class="text-xs font-medium text-slate-500">{@ seo_settings @}</p>
                <div>
                    <label class="block text-xs text-slate-400 mb-1">{@ meta_description @}</label>
                    <textarea name="meta_description" rows="2"
                              class="w-full text-xs px-3 py-2 border border-slate-200 dark:border-slate-700 rounded-xl dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:border-emerald-500"
                              placeholder="{@ meta_desc_placeholder @}">{{ $post['meta_description'] }}</textarea>
                </div>
                <div>
                    <label class="block text-xs text-slate-400 mb-1">{@ share_text @} <span id="shareCount" class="text-slate-400"></span></label>
                    <textarea name="share_text" id="shareText" rows="3" maxlength="500"
                              class="w-full text-xs px-3 py-2 border border-slate-200 dark:border-slate-700 rounded-xl dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:border-emerald-500">{{ $post['share_text'] ?? '' }}</textarea>
                    <p class="text-xs text-slate-400 mt-1">{@ share_text_hint @}</p>
                    <?php if (!empty($post['share_text_auto'])): ?>
                    <p class="text-xs text-slate-500 mt-1">{@ share_text_generated @}<br><?= nl2br(htmlspecialchars((string)$post['share_text_auto'], ENT_QUOTES, 'UTF-8')) ?></p>
                    <?php endif; ?>
                    <p id="shareOver" class="hidden text-xs text-rose-600 mt-1">{@ share_text_over @}</p>
                    <!-- X card preview (summary_large_image is 1.91:1; X crops the image to that box) -->
                    <p class="text-xs text-slate-400 mt-3 mb-1">{@ x_card_preview @}</p>
                    <div class="rounded-xl border border-slate-200 dark:border-slate-700 overflow-hidden text-xs">
                        <div id="xCardImg" class="bg-slate-100 dark:bg-slate-800" style="aspect-ratio:1.91/1;background-size:cover;background-position:center"></div>
                        <div class="px-3 py-2">
                            <p class="text-slate-400"><?= htmlspecialchars((string)parse_url(Env::get('SITE_URL', ''), PHP_URL_HOST), ENT_QUOTES, 'UTF-8') ?></p>
                            <p id="xCardTitle" class="font-medium overflow-hidden" style="white-space:nowrap;text-overflow:ellipsis"></p>
                            <p id="xCardDesc" class="text-slate-500" data-auto="{{ $post['meta_description_auto'] ?? '' }}"></p>
                        </div>
                    </div>
                    <script>
                    (function () {
                        var t = document.getElementById('titleInput'), d = document.querySelector('textarea[name="meta_description"]'),
                            img = document.getElementById('featuredImagePreview'), box = document.getElementById('xCardImg'),
                            ct = document.getElementById('xCardTitle'), cd = document.getElementById('xCardDesc');
                        function clip(s, n) { return s.length > n ? s.slice(0, n) + '…' : s; }
                        function update() {
                            ct.textContent = t ? t.value : '';
                            cd.textContent = clip((d && d.value) || cd.dataset.auto || '', 100);
                            var src = img && !img.classList.contains('hidden') ? img.getAttribute('src') : '';
                            box.style.backgroundImage = src ? 'url("' + src.replace(/"/g, '%22') + '")' : 'none';
                        }
                        [t, d].forEach(function (el) { if (el) el.addEventListener('input', update); });
                        if (img) new MutationObserver(update).observe(img, { attributes: true, attributeFilter: ['src', 'class'] });
                        update();
                    })();
                    </script>
                    <script>
                    (function () {
                        // X weighted count (see core/ShareText.php): weight 1 in these ranges, else 2; URLs 23; +24 for the appended link
                        var light = [[0, 0x10FF], [0x2000, 0x200D], [0x2010, 0x201F], [0x2032, 0x2037]];
                        function weight(s) {
                            var w = 0, rest = s.replace(/https?:\/\/\S+/g, function () { w += 23; return ''; });
                            for (var ch of rest) { var c = ch.codePointAt(0), l = false; for (var r of light) { if (c >= r[0] && c <= r[1]) { l = true; break; } } w += l ? 1 : 2; }
                            return w;
                        }
                        var ta = document.getElementById('shareText'), out = document.getElementById('shareCount'), over = document.getElementById('shareOver');
                        function update() { var w = ta.value === '' ? 0 : weight(ta.value) + 24; out.textContent = ta.value === '' ? '' : '(' + w + ' / 280)'; over.classList.toggle('hidden', w <= 280); }
                        ta.addEventListener('input', update); update();
                    })();
                    </script>
                </div>
                <div>
                    <label class="block text-xs text-slate-400 mb-1">{@ meta_keywords @}</label>
                    <input type="text" name="meta_keywords" value="{{ $post['meta_keywords'] }}"
                           class="w-full text-xs px-3 py-2 border border-slate-200 dark:border-slate-700 rounded-xl dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:border-emerald-500">
                </div>
            </div>

            <!-- Media upload (allowed even during new creation; the first upload makes the server auto-generate a draft) -->
            <div class="bg-white dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl p-4">
                <p class="text-xs font-medium text-slate-500 mb-2"><svg class="w-4 h-4 inline-block align-text-bottom mr-1" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24" aria-hidden="true"><path d="m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57A4 4 0 1 1 18 8.84l-8.59 8.57a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg>{@ attachments @}</p>
                <input type="file" id="mediaFile" accept="image/*,.pdf,.csv" class="text-xs w-full">
                <button type="button" onclick="uploadMedia()" class="mt-2 w-full text-xs bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 py-2 rounded-xl transition-colors">
                    {@ upload @}
                </button>
            </div>
        </div>
    </div>
</form>

<script>
var postId = '{{ $post['id'] }}';
var adminPath = '{{ $adminPath }}';
var msgUploadSuccess = '{@ upload_success @}';
var msgError = '{@ error_label @}';
// 添付一覧・削除・文字数カウントのメッセージ
var msgInsertLabel   = '{@ media_insert @}';
var msgDeleteLabel   = '{@ media_delete @}';
var msgDeleteConfirm = '{@ media_delete_confirm @}';
var msgDeleteInuse   = '{@ media_delete_inuse @}';
var msgChars         = '{@ charcount_chars @}';
var msgTitleCaution  = '{@ charcount_title_caution @}';
var titleMax         = parseInt('{{ $titleMax }}', 10) || 255;
// ':max' is filled in here because {@ @} is baked at compile time and cannot interpolate.
var msgTitleOver     = '{@ charcount_title_over @}'.replace(':max', titleMax);
var msgBodyThin      = '{@ charcount_body_thin @}';
var msgBodyStandard  = '{@ charcount_body_standard @}';
var msgBodyRich      = '{@ charcount_body_rich @}';

function escAttr(s) {
    return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;')
                    .replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function csrfToken() {
    var el = document.querySelector('input[name="_csrf_token"]');
    return el ? el.value : '';
}

// 画像アップロードで自動生成された下書きの id を採用する。
// 以後の保存・アップロードは同じ行を更新する（二重作成を防ぐ）。
function adoptPostId(id) {
    if (!id) return;
    postId = String(id);
    var f = document.getElementById('postIdField');
    if (f && !f.value) { f.value = id; }
}

// プレビューはサーバー側 MarkdownCompiler を共有（ルビ/傍点も保存後と完全一致）
function switchTab(tab) {
    var editor  = document.getElementById('editorArea');
    var preview = document.getElementById('previewArea');
    var tE = document.getElementById('tabEdit');
    var tP = document.getElementById('tabPreview');

    if (tab === 'edit') {
        editor.classList.remove('hidden');
        preview.classList.add('hidden');
        tE.classList.add('bg-slate-100', 'dark:bg-slate-800', 'font-medium');
        tP.classList.remove('font-medium');
    } else {
        editor.classList.add('hidden');
        preview.classList.remove('hidden');
        tP.classList.add('bg-slate-100', 'dark:bg-slate-800', 'font-medium');
        tE.classList.remove('font-medium');
        preview.innerHTML = '<p class="text-slate-400 text-sm">…</p>';
        var fd = new URLSearchParams();
        fd.append('content_markdown', editor.value);
        fd.append('_csrf_token', csrfToken());
        // The table of contents, the sponsored notice and blocks depend on these, as on save
        var f = document.getElementById('editForm');
        if (f.elements['show_toc'] && f.elements['show_toc'].checked) fd.append('show_toc', '1');
        if (f.elements['is_sponsored'] && f.elements['is_sponsored'].checked) fd.append('is_sponsored', '1');
        if (f.elements['lang']) fd.append('lang', f.elements['lang'].value);
        fetch('/' + adminPath + '/preview', { method: 'POST', body: fd })
            .then(function(r) { return r.json(); })
            .then(function(d) { preview.innerHTML = d.success ? d.html : (msgError + ': ' + (d.message || '')); })
            .catch(function() { preview.innerHTML = '<p class="text-rose-500 text-sm">' + msgError + '</p>'; });
    }
}

// 選択範囲をルビ／傍点記法で囲む
function wrapSelection(before, after, fallback) {
    var ta = document.getElementById('editorArea');
    var s = ta.selectionStart, e = ta.selectionEnd;
    var sel = ta.value.substring(s, e) || fallback;
    ta.value = ta.value.substring(0, s) + before + sel + after + ta.value.substring(e);
    ta.focus();
    ta.selectionStart = s + before.length;
    ta.selectionEnd = s + before.length + sel.length;
}
function insertRuby()   { wrapSelection('｜', '《》', '漢字'); }
function insertBouten() { wrapSelection('《《', '》》', '文字'); }
// 囲み記法・カードを行単位で挿入（選択中の文章は中身になる）
function insertContainer(kind) {
    var open = {
        quote: ':::quote {@ insert_quote_source @}|https://',
        box:   ':::box summary {@ insert_box_title @}',
        say:   ':::say speaker-slug'
    };
    // braces split so the template compiler leaves them alone
    if (kind === 'card') { wrapSelection('\n{' + '{ card:', ' }' + '}\n', 'post-slug'); return; }
    wrapSelection('\n' + open[kind] + '\n', '\n:::\n', '{@ insert_container_body @}');
}

function updateTypeUI() {
    var type = document.querySelector('input[name="type"]:checked').value;
    var postOnly = document.querySelectorAll('.post-only');
    postOnly.forEach(function(el) {
        el.style.display = type === 'post' ? '' : 'none';
    });
    var pageOnly = document.querySelectorAll('.page-only');
    pageOnly.forEach(function(el) {
        el.style.display = type === 'page' ? '' : 'none';
    });
}

// 予約公開日時フィールドの表示切替
function updateScheduleUI() {
    var status = document.getElementById('statusSelect').value;
    var field = document.getElementById('scheduleField');
    if (field) field.style.display = (status === 'scheduled') ? '' : 'none';
}

// アイキャッチのプレビュー更新
function updateFeaturedPreview() {
    var input = document.getElementById('featuredImageInput');
    var img   = document.getElementById('featuredImagePreview');
    if (!input || !img) return;
    var v = input.value.trim();
    if (v) { img.src = v; img.classList.remove('hidden'); }
    else   { img.removeAttribute('src'); img.classList.add('hidden'); }
}

// アイキャッチを本文画像と同じ /upload API でアップロード（EXIF除去・attachments記録を共有）
function uploadFeatured() {
    var el = document.getElementById('featuredFile');
    var file = el && el.files[0];
    if (!file) return; // postId 不要（無ければサーバーが下書きを自動生成）

    var fd = new FormData();
    fd.append('file', file);
    fd.append('post_id', postId || '');
    fd.append('_csrf_token', csrfToken());

    fetch('/' + adminPath + '/upload', { method: 'POST', body: fd })
        .then(function(r) { return r.json(); })
        .then(function(d) {
            if (d.success) {
                adoptPostId(d.post_id);
                var fi = document.getElementById('featuredImageInput');
                fi.value = d.url;
                updateFeaturedPreview();
                addAttachmentToList(d.url, file.name, true); // 添付一覧へ反映
            } else {
                alert(msgError + ': ' + d.message);
            }
        });
}

// アイキャッチをクリア（保存時にフォールバックで再解決される）
function clearFeatured() {
    var fi = document.getElementById('featuredImageInput');
    if (fi) { fi.value = ''; updateFeaturedPreview(); }
}

function uploadMedia() {
    var file = document.getElementById('mediaFile').files[0];
    if (!file) return; // postId 不要（無ければサーバーが下書きを自動生成）

    var fd = new FormData();
    fd.append('file', file);
    fd.append('post_id', postId || '');
    fd.append('_csrf_token', csrfToken());

    fetch('/' + adminPath + '/upload', { method: 'POST', body: fd })
        .then(function(r) { return r.json(); })
        .then(function(d) {
            if (d.success) {
                adoptPostId(d.post_id);
                var editor = document.getElementById('editorArea');
                var isImage = /image\//.test(file.type);
                var md = isImage
                    ? '\n![' + file.name + '](' + d.url + ')\n'
                    : '\n[' + file.name + '](' + d.url + ')\n';
                editor.value += md;
                updateBodyCount(); // 文字数を更新
                // アイキャッチ未設定なら最初の画像を候補として差し込む
                var fi = document.getElementById('featuredImageInput');
                if (isImage && fi && fi.value.trim() === '') {
                    fi.value = d.url;
                    updateFeaturedPreview();
                }
                addAttachmentToList(d.url, file.name, isImage); // 添付一覧へ反映
                alert(msgUploadSuccess + ': ' + d.url);
            } else {
                alert(msgError + ': ' + d.message);
            }
        });
}

// ============================================================
// 文字数カウント（コードポイント単位＝和文も半角も1文字）
// クライアント側のみ。サーバー負荷・FPC への影響はゼロ。
// ============================================================
function cpLen(s) { return [...String(s)].length; }

function updateTitleCount() {
    var ta  = document.getElementById('titleInput');
    var out = document.getElementById('titleCount');
    if (!ta || !out) return;
    var n = cpLen(ta.value);
    out.textContent = n + ' / ' + titleMax + ' ' + msgChars;
    out.classList.remove('text-slate-400', 'text-amber-500', 'text-rose-500');
    if (n >= titleMax)                  { out.classList.add('text-rose-500');  out.title = msgTitleOver; }
    else if (n > Math.floor(titleMax * 0.9)) { out.classList.add('text-amber-500'); out.title = msgTitleCaution; }
    else               { out.classList.add('text-slate-400'); out.title = ''; }
}

function updateBodyCount() {
    var ta    = document.getElementById('editorArea');
    var out   = document.getElementById('bodyCount');
    var guide = document.getElementById('bodyGuide');
    if (!ta || !out) return;
    var n = cpLen(ta.value);
    out.textContent = n.toLocaleString() + ' ' + msgChars;
    if (guide) {
        guide.classList.remove('text-amber-500', 'text-emerald-500', 'text-sky-500');
        if (n < 1000)      { guide.textContent = msgBodyThin;     guide.classList.add('text-amber-500'); }
        else if (n < 3000) { guide.textContent = msgBodyStandard; guide.classList.add('text-emerald-500'); }
        else               { guide.textContent = msgBodyRich;     guide.classList.add('text-sky-500'); }
    }
}

// ============================================================
// 添付画像の本文挿入・物理削除・一覧追加
// ============================================================
function refreshAttachmentEmpty() {
    var list  = document.getElementById('attachmentList');
    var empty = document.getElementById('attachmentEmpty');
    if (!list || !empty) return;
    empty.classList.toggle('hidden', list.children.length > 0);
}

// カーソル位置へ ![alt](url) を挿入（再アップロード不要で使い回す）
function insertAttachment(btn) {
    var item = btn.closest('.attachment-item');
    if (!item) return;
    var url = item.getAttribute('data-insert');
    var alt = item.getAttribute('data-alt') || '';
    var ta  = document.getElementById('editorArea');
    var s = ta.selectionStart, e = ta.selectionEnd;
    var snippet = '\n![' + alt + '](' + url + ')\n';
    ta.value = ta.value.substring(0, s) + snippet + ta.value.substring(e);
    ta.focus();
    ta.selectionStart = ta.selectionEnd = s + snippet.length;
    updateBodyCount();
}

// 物理削除（確認必須・本文使用中なら警告強化・本文は自動書き換えしない）
function deleteAttachment(btn) {
    var item = btn.closest('.attachment-item');
    if (!item) return;
    var filename = item.getAttribute('data-filename');
    // 使用中判定: 本文 Markdown に当該ファイル名が含まれるか（クライアント側走査）
    var body  = document.getElementById('editorArea').value;
    var inUse = filename && body.indexOf(filename) !== -1;
    if (!confirm(inUse ? msgDeleteInuse : msgDeleteConfirm)) return;

    var fd = new FormData();
    fd.append('post_id', postId || '');
    fd.append('filename', filename);
    fd.append('_csrf_token', csrfToken());
    fetch('/' + adminPath + '/api/media/delete', { method: 'POST', body: fd })
        .then(function(r) { return r.json(); })
        .then(function(d) {
            if (d.success) { item.remove(); refreshAttachmentEmpty(); }
            else { alert(msgError + ': ' + (d.message || '')); }
        })
        .catch(function() { alert(msgError); });
}

// アップロード成功時に一覧へ追加（直後は下書き＝管理配信URLで表示）
function addAttachmentToList(url, fileName, isImage) {
    var list = document.getElementById('attachmentList');
    if (!list) return;
    var filename = url.split('/').pop();
    var thumb = '/' + adminPath + '/assets/' + filename;
    var div = document.createElement('div');
    div.className = 'attachment-item border border-slate-100 dark:border-slate-800 rounded-xl p-2 text-center';
    div.setAttribute('data-filename', filename);
    div.setAttribute('data-insert', url);
    div.setAttribute('data-alt', fileName);
    var media = isImage
        ? '<img src="' + escAttr(thumb) + '" alt="" class="w-full h-20 object-cover rounded-lg mb-1" loading="lazy">'
        : '<div class="w-full h-20 flex items-center justify-center bg-slate-50 dark:bg-slate-900 rounded-lg mb-1"><svg class="w-8 h-8 text-slate-400" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24" aria-hidden="true"><path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/></svg></div>';
    div.innerHTML = media +
        '<p class="text-[10px] text-slate-400 truncate mb-1" title="' + escAttr(fileName) + '">' + escAttr(fileName) + '</p>' +
        '<div class="flex gap-1">' +
        '<button type="button" onclick="insertAttachment(this)" class="flex-1 text-[10px] bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 py-1 rounded-lg transition-colors">' + escAttr(msgInsertLabel) + '</button>' +
        '<button type="button" onclick="deleteAttachment(this)" class="text-[10px] text-rose-400 hover:text-rose-600 px-2 py-1">' + escAttr(msgDeleteLabel) + '</button>' +
        '</div>';
    list.appendChild(div);
    refreshAttachmentEmpty();
}

(function() {
    var t = document.getElementById('titleInput');
    var b = document.getElementById('editorArea');
    if (t) t.addEventListener('input', updateTitleCount);
    if (b) b.addEventListener('input', updateBodyCount);
})();

updateTypeUI();
updateScheduleUI();
updateTitleCount();
updateBodyCount();
</script>

{% include 'admin/_layout_foot' %}
